<script setup>
import {ref,onMounted,watch} from 'vue'
import {request} from './client'
import Icon from '../Icon.vue'
const props=defineProps({profile:{type:String,default:''}}),emit=defineEmits(['room','navigate','refresh'])
const rows=ref([]),page=ref(0),more=ref(false),busy=ref(false),error=ref('')
let sequence=0
const labels={available:'Available to enrol',unlocked:'Unlocked',pending:'Slip submitted · awaiting payment approval',payment:'Payment required'}
async function load(){const run=++sequence;busy.value=true;error.value='';try{const data=await request('learning_spaces','classes',{profile:props.profile,page:page.value});if(run===sequence){rows.value=data.classes;more.value=data.has_more}}catch(e){if(run===sequence)error.value=e.message}finally{if(run===sequence)busy.value=false}}
async function join(r){busy.value=true;error.value='';try{await request(r.programme?'teaching':'catalog',r.programme?'enroll_programme':'join_class',r.programme?{programme:r.programme}:{classroom:r.name});await load();emit('refresh');if(r.fee_mode!=='Free'||r.programme)emit('navigate','payments')}catch(e){error.value=e.message}finally{busy.value=false}}

watch(()=>props.profile,()=>{page.value=0;load()});onMounted(load)
</script>
<template><section class="student-classrooms"><header class="page-heading"><div><span class="eyebrow">YOUR NEXT CHAPTER</span><h1>My classrooms</h1><p>{{profile?'Classes and programme modules from your selected provider.':'Your enrolled classes. Choose a followed provider above to discover more.'}}</p></div><button class="button subtle" :disabled="busy" @click="load">Refresh</button></header><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="busy" role="status">Loading…</p><div class="learning-class-grid"><article v-for="r in rows" :key="r.name" class="panel"><div class="class-cover" :class="{photo:!!r.cover_image}"><img v-if="r.cover_image" :src="r.cover_image" alt=""/><div v-else class="class-cover-art" aria-hidden="true"><Icon name="BookOpen" :size="58"/><span class="cover-orbit"></span></div><span class="cover-label">{{r.programme?'Programme module':r.fee_mode==='Free'?'Free learning':'Live & learning'}}</span></div><div class="class-copy"><small>{{r.programme?'Programme module':'Classroom'}}</small><h2>{{r.title}}</h2><div class="class-teacher"><span class="teacher-monogram">{{r.teacher_name?.[0]||'T'}}</span><div><strong>{{r.teacher_name}}</strong><small v-if="r.teacher_id">{{r.teacher_id}}</small></div></div><span class="class-status" :class="r.state"><Icon :name="r.state==='unlocked'?'CheckCircle2':r.state==='pending'?'Clock':'BookOpen'" :size="15"/>{{r.state==='unlocked'&&r.payment_approved?'Payment approved · unlocked':labels[r.state]}}</span><p v-if="r.state==='available'">{{r.programme?'One programme invoice includes all its modules.':r.fee_mode==='Free'?'Free class':'Class fee: LKR '+r.fee}}</p><button v-if="r.state==='available'" class="button primary" :disabled="busy" @click="join(r)">{{r.programme?'Enrol in programme':r.fee_mode==='Free'?'Enrol free':'Enrol · prepare payment invoice'}}</button><button v-else-if="r.state==='unlocked'" class="button primary" @click="emit('room',r)">View classroom</button><button v-else class="button subtle" @click="emit('navigate','payments')">{{r.state==='pending'?'View payment review':'Upload payment slip'}}</button></div></article></div><p v-if="!busy&&!rows.length">No classes here yet. Follow a provider in Teachers & institutes and select it above.</p><div class="inline"><button class="button subtle" :disabled="busy||!page" @click="page--;load()">Previous</button><button class="button subtle" :disabled="busy||!more" @click="page++;load()">Next</button></div></section></template>
<style scoped>.learning-class-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:24px;margin:24px 0}.learning-class-grid article{overflow:hidden}.learning-class-grid img{width:100%;height:150px;object-fit:cover}.class-copy{padding:24px;display:grid;gap:16px}.class-copy h2{font-size:21px}.class-copy p{line-height:1.6}.activation-form{padding:24px;margin-top:24px;display:grid;gap:16px}.activation-form input{display:block;padding:14px;border:1px solid var(--student-border);border-radius:10px;margin-top:8px;width:100%}</style>

<style scoped>
.learning-class-grid{grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:26px}.learning-class-grid article.panel{padding:0;border-radius:22px;box-shadow:0 6px 24px #30204008;transition:box-shadow .2s,transform .2s;display:flex;flex-direction:column}.learning-class-grid article:hover{box-shadow:0 12px 30px #30204014;transform:translateY(-3px)}.class-cover{height:170px;position:relative;overflow:hidden;background:linear-gradient(135deg,var(--student-soft),color-mix(in srgb,var(--student-accent) 25%,white))}.class-cover img{height:100%;object-fit:cover}.class-cover-art{height:100%;display:grid;place-items:center;color:var(--student-accent)}.class-cover-art>svg{transform:rotate(-10deg);z-index:1}.cover-orbit{position:absolute;width:140px;height:140px;border:1px solid color-mix(in srgb,var(--student-accent) 22%,transparent);border-radius:50%;right:20px;top:-30px}.cover-orbit:after{content:'';position:absolute;width:210px;height:210px;left:-180px;top:85px;border-radius:50%;background:#ffffff55}.cover-label{position:absolute;left:16px;top:16px;padding:7px 10px;border-radius:8px;background:#ffffffed;color:#3c3150;font-size:10px;font-weight:650}.class-copy{flex:1;padding:23px;gap:15px}.class-copy>small{text-transform:uppercase;letter-spacing:.09em;font-size:10px}.class-copy h2{line-height:1.35;margin:0;font-size:21px}.class-teacher{display:flex;align-items:center;gap:10px}.teacher-monogram{height:36px;width:36px;border-radius:50%;background:var(--student-soft);color:var(--student-accent);display:grid;place-items:center}.class-teacher strong{font-size:12px;font-weight:550}.class-teacher small{display:block;font-size:10px;margin-top:4px}.class-status{display:inline-flex;align-items:center;gap:7px;font-size:11px;padding:9px 10px;border-radius:9px;background:var(--student-soft);color:var(--student-ink)}.class-status.unlocked{background:#edf7f1;color:#246343}.class-status.pending{background:#fff5df;color:#795b18}.class-copy>.button{width:100%;margin-top:auto;min-height:42px;justify-content:center}.class-copy>p{font-size:12px}@media(max-width:500px){.learning-class-grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.learning-class-grid article:hover{transform:none}}
</style>
